INSERT INTO cq_zones.source (document) VALUES ('{"title": "CQ zones", "schema": "cq_zones", "owner": "CQ Communications, Inc. / World Wide Radio Operators Foundation (WWROF)", "document_title": "CQ WAZ Zone Definitions", "document": "cq_waz_list.htm", "edition": "2018-04-01", "url": "https://cqww.com/cq_waz_list.htm", "authority": "CQ''s Worked All Zones (WAZ) award and the CQ World Wide DX Contest define the 40 CQ zones.", "terms": "Copyright (c) World Wide Radio Operators Foundation, Inc. All rights reserved (page footer). CQ magazine''s copy of this list adds: ''(c) CQ Communications, Inc. ... may not be reproduced or republished ... without the express written permission of the publisher. Hyperlinks to this page are permitted.'' This package does not redistribute the page: it links to it, records its SHA-256, and holds the facts from it, credited to CQ.", "adif_version": "3.1.7", "published": {"cq_waz_list.htm": {"url": "https://cqww.com/cq_waz_list.htm", "retrieved": "2026-10-07", "sha256": "44f4ef3d974e27de9e4a81745a29c2f9e6aa5fd889a663534d2e899d46490bff"}}, "facts": ["cq_zones.json"], "derived_note": "derived/entity_zones.json (ours): ADIF DXCC entity -> CQ zones, built from the facts."}'::jsonb);
INSERT INTO cq_zones.code VALUES ('cq_zones', 1, '1', 'Northwestern Zone of North America', NULL, NULL, NULL, NULL, 'cq_waz_list.htm, Zone 1', 'CQ writes ''VE8 the Northwest and VY0 Nunavut Territories west of 102 degrees (Includes the islands of ...)''; the qualifier grammatically governs both territories, so it is recorded as the boundary of both the VE8 and VY0 covers.');
INSERT INTO cq_zones.cover (list, seq, n, dxcc, pas, prefix, boundary) VALUES ('cq_zones', 1, 1, 6, NULL, 'KL', NULL);
