INSERT INTO cq_zones.cover (list, seq, n, dxcc, pas, prefix, boundary) VALUES ('cq_zones', 1, 3, 1, 'NT', 'VE8', 'west of 102 degrees (Includes the islands of Victoria, Banks, Melville, and Prince Patrick)');
INSERT INTO cq_zones.cover (list, seq, n, dxcc, pas, prefix, boundary) VALUES ('cq_zones', 1, 4, 1, 'NU', 'VY0', 'west of 102 degrees (Includes the islands of Victoria, Banks, Melville, and Prince Patrick)');
INSERT INTO cq_zones.code VALUES ('cq_zones', 2, '2', 'Northeastern Zone of North America', NULL, NULL, NULL, NULL, 'cq_waz_list.htm, Zone 2', 'Nunavut east of 102 degrees is named without a prefix (prefix null). ''King William. Prince of Wales'' kept as published (period for comma). The exclusion list (Akimiski, Bear Islands, East Pen) omits Fox Island, which Zone 4 assigns to Zone 4 alongside them.');
