INSERT INTO cq_zones.code VALUES ('cq_zones', 8, '8', 'West Indies Zone', NULL, NULL, NULL, NULL, 'cq_waz_list.htm, Zone 8', 'Published ''KP5 (Navassa Is.)'' is an evident error: KP1 is already ''(Navassa Is.)'', and KP5 is Desecheo I. (ARRL; ADIF 43). The KP5 cover is mapped by its prefix to ADIF 43 (Desecheo); the published label is kept here only. Also as published: ''KP2 Virgin Islands)'' (no opening parenthesis). PJ5 (Eustatius) and PJ6 (Saba) both map to ADIF 519 (Saba & St. Eustatius).');
