INSERT INTO cq_zones.code VALUES ('cq_zones', 12, '12', 'Southwest Zone of South America', NULL, NULL, NULL, NULL, 'cq_waz_list.htm, Zone 12; Notes', 'Each CE0 is mapped by the area CQ names (Easter 47; Juan Fernandez 125; San Felix 217); 3Y by ''Peter I'' (199). Notes: ''The boundaries of CQ zones 12, 13, 29, 30, 32, 38 and 39 converge at the South Pole.'' The two South Pole stations are callsigns, not prefixes; they are recorded with the callsign in the prefix field and are attached to every zone the note lists.');
