INSERT INTO cq_zones.code VALUES ('cq_zones', 16, '16', 'Eastern Zone of Europe', NULL, NULL, NULL, NULL, 'cq_waz_list.htm, Zone 16', 'Published run ''UA1, UA2(except for RA2 and UA2-UI2), UA3. UA4,  UA5,UA6, UA7,UA9,UA9 (S,T,W)'' split into one cover per prefix (''UA3.'' recorded as ''UA3''). AMBIGUOUS: (a) UA2 is Kaliningrad''s prefix (ARRL; Zone 15 here), so ''UA2 except for RA2 and UA2-UI2'' has no evident remainder; mapped by prefix to ADIF 126 Kaliningrad, flagged. (b) A bare ''UA9'' precedes ''UA9 (S,T,W)''; a bare UA9 would contradict Zones 17-18, so it is likely a stray duplicate; kept as published and mapped by prefix to ADIF 15 (Asiatic Russia). UA9 S/T/W (Orenburg, Bashkortostan per ADIF subdivisions) are ADIF 15 Asiatic Russia.');
