INSERT INTO cq_zones.code VALUES ('cq_zones', 32, '32', 'New Zealand Zone', NULL, NULL, NULL, NULL, 'cq_waz_list.htm, Zone 32; Notes', 'Multi-entity labels split one cover per ADIF entity: E5 (North Cook 191, South Cook 234); FO (French Polynesia 175, Austral I. 508; the ''but NOT Marquesas and Clipperton'' wording is kept on the French Polynesia cover); VP6 (Pitcairn 172, Ducie 513); 3D2 (Fiji 176, Rotuma 460, Conway Reef 489). As published: ''FK New Caledonia but NOT Chesterfield Is.)'' lacks its opening parenthesis. Notes: ''The boundaries of CQ zones 12, 13, 29, 30, 32, 38 and 39 converge at the South Pole.'' The two South Pole stations are callsigns, not prefixes; they are recorded with the callsign in the prefix field and are attached to every zone the note lists.');
