INSERT INTO cq_zones.code VALUES ('cq_zones', 38, '38', 'South African Zone', NULL, NULL, NULL, NULL, 'cq_waz_list.htm, Zone 38; Notes', '3Y mapped by the area CQ names (Bouvet Is., ADIF 24). ''3DA (Swaziland)'' = ADIF 468 (Kingdom of Eswatini). Notes: ''The boundaries of CQ zones 12, 13, 29, 30, 32, 38 and 39 converge at the South Pole.'' The two South Pole stations are callsigns, not prefixes; they are recorded with the callsign in the prefix field and are attached to every zone the note lists.');
