INSERT INTO cq_zones.code VALUES ('cq_zones', 39, '39', 'Madagascar Zone', NULL, NULL, NULL, NULL, 'cq_waz_list.htm, Zone 39; Notes', 'D6 mapped to ADIF 411 (Comoros, current; 39 is deleted). VK0 mapped by the area CQ names (Heard Is., ADIF 111). As published: ''Mautitius Is.'' (Mauritius). FT-W and FT-Z keep the published U+2011 non-breaking hyphen; the other FT- prefixes use an ASCII hyphen. Notes: ''The boundaries of CQ zones 12, 13, 29, 30, 32, 38 and 39 converge at the South Pole.'' The two South Pole stations are callsigns, not prefixes; they are recorded with the callsign in the prefix field and are attached to every zone the note lists.');
